	def confirmSelectionBUTTONO(self, valuesDict=None, typeId=None, devId=None):
			"""Processes the single-output config selection: takes the gpio/outType/initialValue chosen in the dialog and merges it into the device's deviceDefs JSON, detects pin conflicts across channels, updates inverse/initial device states, builds a pinMappings string, and flags that an initial value must be sent. Returns the updated values dictionary.
			
			Inputs:
			    valuesDict (indigo.Dict): Dialog values holding gpio/outType/initialValue and deviceDefs; updated with pinMappings and deviceDefs
			    typeId (str): Device type id used to determine the number of channels
			    devId (int or str): Device id; converted to int to fetch the Indigo device and its props
			Outputs:
			    indigo.Dict: The valuesDict updated with pinMappings and deviceDefs (returned early unchanged if devId is invalid)
			"""
			nChannels = self.getTypeIDLength(typeId)

			try:
				idevId = int(devId)
				if idevId != 0:
					dev = indigo.devices[idevId]
					props = dev.pluginProps
			except:
				dev = ""
				props = ""
				piNumberExisting = ""
				return valuesDict

			try:
				xxx = json.loads(valuesDict["deviceDefs"])
			except:
				xxx=[]
			try:
				oldxxx = json.loads(props["deviceDefs"])
			except:
				oldxxx = copy.deepcopy(xxx)
				for n in range(len(oldxxx)):
					oldxxx[n]["initialValue"] ="x"

			inS = "0"
			inSi = int(inS)
			if valuesDict["gpio"] == "0":
				xxx[inSi] = {}
			else:
				xxx[inSi] = {"gpio": valuesDict["gpio"],"outType": valuesDict["outType"],"initialValue": valuesDict["initialValue"]}
			pinMappings = ""
			# clean up
			for n in range(nChannels):
				if "gpio" in xxx[n]:
					if xxx[n]["gpio"] == "0":
						del xxx[n]
					if	len(oldxxx) < (n+1) or "initialValue" not in oldxxx[n] or (xxx[n]["initialValue"] != oldxxx[n]["initialValue"]):
						self.sendInitialValue = dev.id
					pinMappings += "{}".format(n) + ":" + xxx[n]["gpio"]+ "," + xxx[n]["outType"]+ "," + xxx[n]["initialValue"] + "|"
					if "inverse" in dev.states:
						self.updateStateOnServerlog(dev, "inverse", "yes" if xxx[n]["outType"] == "1"  else "no")
					elif "inverse_{:2d}".format(n) in dev.states:
						self.updateStateOnServerlog(dev, "inverse_{:2d}".format(n), "yes" if xxx[n]["outType"] == "1"  else "no")

					if "initial" in dev.states:
						self.updateStateOnServerlog(dev, "initial", xxx[n]["initialValue"])
					elif "initial{:2d}".format(n) in dev.states:
						self.updateStateOnServerlog(dev, "initial{:2d}".format(n), xxx[n]["initialValue"] )

					for l in range(n, nChannels):
						if l == n: continue
						if "gpio" not in xxx[l]:	continue
						if xxx[l]["gpio"] == "0":	continue
						if xxx[n]["gpio"] == xxx[l]["gpio"]:
							pinMappings = "error # {} same pin as #{}".format(n, l)
							xxx[l]["gpio"] = "0"
							valuesDict["gpio"] = "0"
							break
					if "error" in pinMappings: break

			valuesDict["pinMappings"] = pinMappings
			valuesDict["deviceDefs"] = json.dumps(xxx)
			self.indiLOG.log(10,"confirmSelectionBUTTONO len:{};  deviceDefs:{}".format(nChannels, valuesDict["deviceDefs"]))
			return valuesDict

