	def updateADC121(self,dev,data,whichKeysToDisplay):
		"""Updates an ADC121 analog sensor device: takes the raw ADC reading and, based on the configured gas/sensor type (MQ7, MQ9, MQ4, MQ3, MQ131, A13XX hall, TA12_200 current, plain adc, etc.), converts it via sensor-specific resistance/log-curve math into ppm/mV/angle values, then writes the scaled value and raw ADC to device states.
		
		Inputs:
		    dev (indigo.Device): The ADC121-based sensor device to update
		    data (dict): Sensor reading dict containing the 'adc' raw value
		    whichKeysToDisplay (str): Which state key(s) to show in the device status column
		Outputs:
		    None: Computes converted readings and queues device state/status updates; sets the icon
		"""
		try:
			input = "adc"
			props = dev.pluginProps
			xType = props["type"]
			pp = {"offset": props["offset"], "mult":props["mult"], "unit": "ppm", "format":"%2d"}

			if "{}".format(data[input]).find("bad") >-1:
					self.addToStatesUpdateDict(dev.id, "status", "no sensor data - disconnected?")
					self.setIcon(dev,props, "SensorOff-SensorOn",0)
					return

			self.setIcon(dev,props, "SensorOff-SensorOn",1)
			if input in data:
					if data[input] != "":
						ADC = data[input]
						MaxBits = 4095.	  # 12 bits
						Vcc		= 5000.	  # mVolt max

						if	 xType.find("MQ") > -1:
							try:	Vca		= float(dev.props["Vca"] )	  # mVolt  at clean Air / calibration
							except: Vca		= 3710.

						if	xType =="MQ7": #CO
							pp["unit"]		="ppm CO"
							pp["format"]	="%.2f"
							RR1 = 0.22
							RR2 = 0.02
							C1	= 10.
							C2	= 1000.
							k = math.log(RR1/RR2) / math.log(C1/C2)
							a = math.exp(  math.log(RR1) -	k * math.log(C1)  )
							RR = (MaxBits/ADC -1.) / (Vcc/Vca -1.)
							val = math.pow(RR/a,1./k)

						elif   xType =="MQ9": # CO
							pp["unit"]		="ppm CO"
							pp["format"]	="%.2f"
							RR1 = 1.5
							RR2 = 0.78
							C1	= 200
							C2	= 1000.
							k = math.log(RR1/RR2) / math.log(C1/C2)
							a = math.exp(  math.log(RR1) -	k * math.log(C1)  )
							RR = (MaxBits/ADC -1.) / (Vcc/Vca -1.)
							val = math.pow(RR/a,1./k)

						elif   xType =="MQ9-5LPG": # LPG
							pp["unit"]		="ppm LPG"
							pp["format"]	="%.2f"
							RR1 = 2.0
							RR2 = 0.31
							C1	= 200
							C2	= 10000.
							k = math.log(RR1/RR2) / math.log(C1/C2)
							a = math.exp(  math.log(RR1) -	k * math.log(C1)  )
							RR = (MaxBits/ADC -1.) / (Vcc/Vca -1.)
							val = math.pow(RR/a,1./k)

						elif   xType =="MQ9-5CH4": # CH4
							pp["unit"]		="ppm CH4"
							pp["format"]	="%.2f"
							RR1 = 3.0
							RR2 = 0.69
							C1	= 200
							C2	= 10000.
							k = math.log(RR1/RR2) / math.log(C1/C2)
							a = math.exp(  math.log(RR1) -	k * math.log(C1)  )
							RR = (MaxBits/ADC -1.) / (Vcc/Vca -1.)
							val = math.pow(RR/a,1./k)

						elif  xType =="MQ4": # LNG
							pp["unit"]		="ppm CNG"
							pp["format"]	="%.2f"
							RR1 = 2.5
							RR2 = 0.42
							C1	= 20.
							C2	= 10000.
							k = math.log(RR1/RR2) / math.log(C1/C2)
							a = math.exp(  math.log(RR1) -	k * math.log(C1)  )
							RR = (MaxBits/ADC -1.) / (Vcc/Vca -1.)
							val = math.pow(RR/a,1./k)


						elif xType =="MQ3-Alcohol": #alcohol
							pp["unit"]		="Alcohol mg/l"
							pp["format"]	="%.2f"
							RR1 = 2.2
							RR2 = 0.11
							C1	= 0.1
							C2	= 10.
							k = math.log(RR1/RR2) / math.log(C1/C2)
							a = math.exp(  math.log(RR1) -	k * math.log(C1)  )
							RR = (MaxBits/ADC -1.) / (Vcc/Vca -1.)
							val = math.pow(RR/a,1./k)

						elif xType =="MQ3-Benzene": #alcohol
							pp["unit"]		="Benzene mg/l"
							pp["format"]	="%.2f"
							RR1 = 3.
							RR2 = 0.75
							C1	= 0.1
							C2	= 10.
							k = math.log(RR1/RR2) / math.log(C1/C2)
							a = math.exp(  math.log(RR1) -	k * math.log(C1)  )
							RR = (MaxBits/ADC -1.) / (Vcc/Vca -1.)
							val = math.pow(RR/a,1./k)

						elif xType =="MQ131": #Ozone
							pp["unit"]		="ppm Ozon"
							pp["format"]	="%.2f"
							RR1 = 3
							RR2 = 0.3
							C1	= 5.
							C2	= 100.
							k = math.log(RR1/RR2) / math.log(C1/C2)
							a = math.exp(  math.log(RR1) -	k * math.log(C1)  )
							RR = (MaxBits/ADC -1.) / (Vcc/Vca -1.)
							val = math.pow(RR/a,1./k)

						elif xType =="A13XX": # hall effect sensor
							pp["unit"]		="¼"
							pp["format"]	="%.2f"
							val		= (ADC / MaxBits) * 360.0

						elif xType =="TA12_200": # linear current sensor
							pp["unit"]		="mA"
							pp["format"]	="%.1f"
							val		= ADC

						elif xType =="adc": # simple ADC
							pp["unit"]	="mV"
							pp["format"]="%0d"
							val			= ADC *(Vcc/MaxBits)


						ss, ssUI, unit = self.addmultOffsetUnit(val, pp)

						self.setStatusCol( dev, "value", ss, ssUI+unit, whichKeysToDisplay, "","" )
						self.setStatusCol( dev, "adc", ADC, "{}".format(ADC), whichKeysToDisplay,"","" )
		except Exception as e:
			if self.decideMyLog("SensorData"):
				if f"{e}".find("None") == -1: self.indiLOG.log(40,"", exc_info=True)


