	def updateDistance(self, dev, data, whichKeysToDisplay):
			#{"ultrasoundDistance":{"477759402":{"distance":1700.3591060638428}}
		"""Updates an ultrasonic distance sensor device: applies offset/multiply and cutMin/cutMax limits to the raw distance, converts to the configured unit (cm/m/inches/feet), optionally converts a speed reading to the configured speed unit, writes distance/speed/raw states, and sets state color or proximity icon based on a distance limit.
		
		Inputs:
		    dev (indigo.Device): The distance sensor device to update
		    data (dict): Sensor reading dict with 'distance' and optional 'speed' values
		    whichKeysToDisplay (str): Which state key(s) to show in the device status column
		Outputs:
		    None: Queues device state/status updates and sets icon/state color
		"""
		try:

			input = "distance"
			if input in data:
				if "{}".format(data[input]).find("bad") >-1:
					self.addToStatesUpdateDict(dev.id, "status", "no sensor data - disconnected?")
					self.setIcon(dev, dev.pluginProps, "SensorOff-SensorOn",0)
					return

				props = dev.pluginProps
				units = "cm"
				dist0 = 1.
				offset= 0.
				multiply=1.
				if	   "dUnits" in props: units  = props["dUnits"]
				try:
					if "offset" in props: offset = float(props["offset"])
				except: pass

				try:
					if "multiply" in props:
						mm = float(props["multiply"])
						if mm != 0: multiply=mm
				except: pass

				raw = round(float(data[input]),2)
				if "distanceRaw" in dev.states: self.addToStatesUpdateDict(dev.id, "distanceRaw", raw)

				if	   "cutMax" in props:
					try:
						raw = min( raw, float(props["cutMax"]))
					except: pass

				if	   "cutMin" in props:
					try:
						raw = max( raw, float(props["cutMin"]))
					except: pass


				distR= (raw+offset)*multiply
				dist = distR
				ud   = "[]"
				if units == "cm":
					ud = " [cm]"
					dist = distR
					dist0 = "{:.1f}{}".format(distR, ud)
				elif units == "m":
					ud = " [m]"
					dist = distR*0.01
					dist0 = "{:.2f}{}".format(dist, ud)
				elif units == "inches":
					ud = ' "'
					dist = distR*0.3937
					dist0 = "{:.1f}{}".format(dist, ud)
				elif units == "feet":
					ud = " '"
					dist = distR*0.03280839895
					dist0 = "{:.2f}{}".format(dist, ud)
				self.setStatusCol(dev, "distance", dist, dist0, whichKeysToDisplay, "","", decimalPlaces = 2)

				if "measuredNumber" in dev.states: self.addToStatesUpdateDict(dev.id, "measuredNumber", raw)

				if "speed" in data:
					try:
						speed = float(data["speed"]) / max(self.speedUnits*100., 0.01)	 # comes in cm/sec
						units = self.speedUnits
						sp = "{}".format(speed)
						ud = "[]"
						if units == 0.01:
							ud = " [cm/s]"
							sp = "{:.1f}".format(speed)
							decimalPlaces = 1
						elif units == 1.0:
							ud = " [m/s]"
							sp = "{:.2f}".format(speed)
							decimalPlaces = 2
						elif units == 0.0254:
							ud = ' [i/s]'
							sp = "{:.1f}".format(speed)
							decimalPlaces = 1
						elif units == 0.348:
							ud = " [f/s]"
							sp = "{:.2f}".format(speed)
							decimalPlaces = 2
						elif units == 0.9144:
							ud = " [y/s]"
							sp = "{:.2f}".format(speed)
							decimalPlaces = 2
						elif units == 3.6:
							ud = " [kmh]"
							sp = "{:.3f}".format(speed)
							decimalPlaces = 2
						elif units == 2.2369356:
							ud = " [mph]"
							sp = "{:.3f}".format(speed)
							decimalPlaces = 2
						self.setStatusCol(dev, "speed", speed, sp+ud, whichKeysToDisplay, "","", decimalPlaces = decimalPlaces)
					except Exception as e:
						if f"{e}".find("None") == -1: self.indiLOG.log(40,"", exc_info=True)

				if not self.setStateColor( dev, props, dist):
					if "actionShortDistanceLimit" in props:
						try: cutoff= float(props["actionShortDistanceLimit"])
						except: cutoff= 50
					else:		cutoff= 50
					if dist < cutoff:
							self.setIcon(dev,props, "SensorOff-SensorOn",1)
					else:
							self.setIcon(dev,props, "SensorOff-SensorOn",0)

		except Exception as e:
			if f"{e}".find("None") == -1: self.indiLOG.log(40,"", exc_info=True)





